__NUXT_JSONP__("/finanzas-publicas/noticias/sistema_nacional_anticorrupcion_sigue_incompleto_271_cargos_vacantes_y_sistemas_estatales_inoperantes", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D){return {data:[{post:{slug:"sistema_nacional_anticorrupcion_sigue_incompleto_271_cargos_vacantes_y_sistemas_estatales_inoperantes",title:"Sistema Nacional Anticorrupción sigue incompleto: 271 cargos vacantes y sistemas estatales inoperantes",date:"2026-01-15T18:32:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F81999083-f0c7-4278-8d22-2b48506fddfc\u002F","img-alt":s,autor:"Elizabeth González-Manrique",link:"https:\u002F\u002Fwww.reporteindigo.com\u002Famp\u002Fnacional\u002Fsistema-nacional-anticorrupcion-sigue-incompleto-271-cargos-vacantes-y-sistemas-estatales-inoperantes-20260114-0087.html",category:"finanzas-publicas",extracto:"A más de 10 años de su creación, el Sistema Nacional Anticorrupción enfrenta rezagos estructurales que se profundizan en los estados: vacantes sin cubrir, comités ciudadanos incompletos y falta de presupuesto mantienen inoperantes a la mayoría de los organismos.",toc:[{id:t,depth:g,text:u},{id:v,depth:g,text:w},{id:x,depth:g,text:y},{id:z,depth:g,text:A},{id:B,depth:g,text:"Hacia un plan nacional "}],body:{type:"root",children:[{type:b,tag:e,props:{},children:[{type:a,value:"A más de una década de su creación, uno de los pilares diseñados para enfrentar la corrupción en México sigue sin consolidarse plenamente. El "},{type:b,tag:f,props:{href:"https:\u002F\u002Fx.com\u002FSESNAOficial?s=20",rel:[h,i,j],target:k},children:[{type:a,value:C}]},{type:a,value:" (SNA), concebido como un eje clave para "},{type:b,tag:c,props:{},children:[{type:a,value:"articular y fortalecer los esfuerzos institucionales"}]},{type:a,value:" contra este fenómeno, avanza de manera dispareja y fragmentada, particularmente en el ámbito estatal, donde su implementación es desigual."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Si bien en el plano federal la actual administración encabezada por la presidenta "},{type:b,tag:f,props:{href:"https:\u002F\u002Fx.com\u002FClaudiashein?s=20",rel:[h,i,j],target:k},children:[{type:a,value:"Claudia Sheinbaum"}]},{type:a,value:" ha impulsado nuevas acciones, como la creación de la "},{type:b,tag:f,props:{href:"https:\u002F\u002Fx.com\u002FBuenGobiernoPue?s=20",rel:[h,i,j],target:k},children:[{type:a,value:"Secretaría Anticorrupción y Buen Gobierno"}]},{type:a,value:", que bajo la conducción de "},{type:b,tag:c,props:{},children:[{type:a,value:D}]},{type:a,value:" ha comenzado a mostrar resultados en poco más de un año de operación, el entramado institucional que debe acompañar esta estrategia aún se encuentra en "},{type:b,tag:c,props:{},children:[{type:a,value:"proceso de consolidación."}]}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"La brecha se profundiza a nivel local. Mientras algunas entidades federativas han logrado fortalecer y poner en marcha sus "},{type:b,tag:c,props:{},children:[{type:a,value:s}]},{type:a,value:" (SEA), otras operan con "},{type:b,tag:c,props:{},children:[{type:a,value:"estructuras incompletas, presupuestos limitados"}]},{type:a,value:" o, en algunos casos, con mecanismos prácticamente inexistentes. Esta disparidad debilita la coordinación nacional y "},{type:b,tag:c,props:{},children:[{type:a,value:"limita la capacidad del Estado"}]},{type:a,value:" para combatir de manera efectiva la corrupción, un problema que requiere instituciones sólidas y homogéneas en todo el territorio."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"De acuerdo con la Secretaría Ejecutiva del Sistema Nacional Anticorrupción (SESNA), tomando en cuenta datos con corte al 30 de septiembre de 2025, 271 de los 770 cargos que deben integrar los SEA continúan vacantes. El rezago es aún mayor en los Comités de Participación Ciudadana."}]},{type:a,value:d},{type:b,tag:l,props:{id:t},children:[{type:b,tag:f,props:{href:"#sistemas-estatales-en-riesgo",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:b,tag:c,props:{},children:[{type:a,value:u}]}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Ante una serie de "},{type:b,tag:c,props:{},children:[{type:a,value:"incumplimientos en los requisitos"}]},{type:a,value:" para mantenerse en funcionamiento, un gran porcentaje de los Sistemas Estatales Anticorrupción son ineficaces ante este mal que solo crece."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Además de que el 35 por ciento de los nombramientos en torno a esos sistemas permanece pendiente, el rezago es aún mayor en los "},{type:b,tag:c,props:{},children:[{type:a,value:r}]},{type:a,value:", necesarios para el funcionamiento de estas estructuras."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"En el caso de los comités necesarios para la instalación de los SEA, el rezago es aún mayor, pues "},{type:b,tag:c,props:{},children:[{type:a,value:"47 por ciento de los nombramientos no se han realizado."}]}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"La situación se agrava en las secretarías ejecutivas estatales, ya que e"},{type:b,tag:c,props:{},children:[{type:a,value:"n 12 entidades no se ha designado a un titular"}]},{type:a,value:" y sólo siete estados: "},{type:b,tag:c,props:{},children:[{type:a,value:"Baja California Sur, Coahuila, Guanajuato, Jalisco, Quintana Roo, Sinaloa y Yucatán"}]},{type:a,value:", cuentan con sistemas plenamente integrados, mientras que 35 por ciento de los SEA, entre los que se encuentran los sistemas de estados como C"},{type:b,tag:c,props:{},children:[{type:a,value:"ampeche, Colima, Guerrero, Morelos y Nayarit"}]},{type:a,value:", operan con menos de la mitad de sus integrantes, lo que los lleva a ser de los más rezagados del país."}]},{type:a,value:d},{type:b,tag:l,props:{id:v},children:[{type:b,tag:f,props:{href:"#inoperancia-el-enemigo-a-vencer",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:b,tag:c,props:{},children:[{type:a,value:w}]}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:b,tag:c,props:{},children:[{type:a,value:"Emiliano Montes de Oca"}]},{type:a,value:", coordinador de Participación ciudadana y proyectos anticorrupción en Ethos, Innovación en Políticas Públicas, menciona que el efecto creado a partir del ámbito nacional en torno al SNA, afectó el funcionamiento de los SEA."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"“Después de que el funcionamiento del SNA quedara de lado, vino toda una ola hacia lo local, "},{type:b,tag:c,props:{},children:[{type:a,value:"dejó de haber un interés hacia los sistemas estatales"}]},{type:a,value:". El ejemplo más claro fue la Ciudad de México, en donde se le retiró el presupuesto, se dejaron de designar a los comités de participación ciudadana, la Secretaría Ejecutiva y pues básicamente se convirtió en un sistema inoperante”, explica."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Entre los problemas que ocasionan que los SEA se mantengan inoperantes, Montes de Oca detecta a las "},{type:b,tag:c,props:{},children:[{type:a,value:"designaciones"}]},{type:a,value:", especialmente de las personas que participan en los "},{type:b,tag:c,props:{},children:[{type:a,value:r}]},{type:a,value:" (CPC). "}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"“Lo vemos así porque pues son el componente ciudadano, es la forma en la que la ciudadanía puede participar en el sistema, puede involucrarse, puede hacer propuestas de política pública, ya sea con las organizaciones civiles, las organizaciones académicas, los empresarios."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"“Entonces, esta figura del comité es súper importante y ahí es principalmente en donde se empieza a dejar de designar. No se designa a la comisión de selección que va a nombrar a ese CPC, luego, entonces, "},{type:b,tag:c,props:{},children:[{type:a,value:"el CPC está incompleto"}]},{type:a,value:" y todo ese componente ciudadano "},{type:b,tag:c,props:{},children:[{type:a,value:"no funciona"}]},{type:a,value:"”, puntualiza Montes de Oca."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Otra de las dificultades a la que se enfrentan los SEA para lograr su plena institución es la parte presupuestaria, pues aunque los comités estén designados no hay un presupuesto, no se pagan honorarios a los integrantes o no se les brinda el apoyo desde las Secretarías Ejecutivas de los sistemas locales para que se puedan hacer las políticas que ellos proponen."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"“El otro componente que deja de funcionar son las "},{type:b,tag:c,props:{},children:[{type:a,value:"Secretarías Ejecutivas"}]},{type:a,value:", como su nombre lo dice, que es el brazo ejecutor de las políticas que se designan o que se crean en el comité coordinador."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"“Entonces, si las secretarías ejecutivas no tienen una cabeza, porque no se ha designado al "},{type:b,tag:c,props:{},children:[{type:a,value:"secretario técnico"}]},{type:a,value:" y sólo tienen a un encargado de despacho o no se les brinda el "},{type:b,tag:c,props:{},children:[{type:a,value:"presupuesto suficiente"}]},{type:a,value:", pues realmente es poco lo que pueden hacer. Considero que estas son las áreas en donde "},{type:b,tag:c,props:{},children:[{type:a,value:"se debilita el sistema"}]},{type:a,value:"”, asegura."}]},{type:a,value:d},{type:b,tag:l,props:{id:x},children:[{type:b,tag:f,props:{href:"#una-d%C3%A9cada-complicada-para-la-instituci%C3%B3n",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:b,tag:c,props:{},children:[{type:a,value:y}]}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"El "},{type:b,tag:c,props:{},children:[{type:a,value:C}]},{type:a,value:" se ha enfrentado a un proceso de debilitamiento a lo largo de varios años, marcado por conflictos internos, amenazas de desaparición y la ausencia de resultados tangibles, lo que "},{type:b,tag:c,props:{},children:[{type:a,value:"dificulta la capacidad para combatir"}]},{type:a,value:" eficazmente la corrupción."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Fue el 27 de mayo de 2015, cuando se publicó la "},{type:b,tag:c,props:{},children:[{type:a,value:"reforma constitucional"}]},{type:a,value:" por la que se creó ese organismo, con el objetivo de combatir este "},{type:b,tag:c,props:{},children:[{type:a,value:"mal que frena el desarrollo económico, político y social"}]},{type:a,value:"; sin embargo, a lo largo de una década de vida, sus resultados han sido pocos y aún se encuentra en miras de lograr su pleno establecimiento."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"En 2012, tres años previos al surgimiento del SNA, el "},{type:b,tag:c,props:{},children:[{type:a,value:"Índice de Percepción de la Corrupción"}]},{type:a,value:" que realiza "},{type:b,tag:c,props:{},children:[{type:a,value:"Transparencia Internacional,"}]},{type:a,value:" situó a México en el "},{type:b,tag:c,props:{},children:[{type:a,value:"puesto 105 de 176,"}]},{type:a,value:" tras obtener un registro de 34 sobre 100 puntos. Pero 12 años después, la situación se mantiene, pues el país cayó hasta el lugar "},{type:b,tag:c,props:{},children:[{type:a,value:"140 de 180"}]},{type:a,value:", al obtener solo 26 puntos en 2024."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"En el otro extremo, "},{type:b,tag:c,props:{},children:[{type:a,value:"Dinamarca"}]},{type:a,value:" obtuvo una puntuación de "},{type:b,tag:c,props:{},children:[{type:a,value:"90 sobre 100"}]},{type:a,value:", tanto en 2012 como en 2024, lo que sitúa a esta nación en la cima como el país menos corrupto del mundo, según esta medición."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"De acuerdo con Emiliano Montes de Oca, este sistema comenzó con demasiado impulso, algo que fue descendiendo hacia 2018. “Recordemos que este sistema se creó desde la reforma constitucional de 2015, en 2016 se crearon las "},{type:b,tag:c,props:{},children:[{type:a,value:"leyes secundarias"}]},{type:a,value:" y a partir de 2017 comenzaron a crearse las "},{type:b,tag:c,props:{},children:[{type:a,value:"leyes locales"}]},{type:a,value:" y con ellas los Sistemas Estatales Anticorrupción."}]},{type:a,value:d},{type:b,tag:l,props:{id:z},children:[{type:b,tag:f,props:{href:"#v%C3%ADctimas-de-corrupci%C3%B3n-en-m%C3%A9xico",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:b,tag:c,props:{},children:[{type:a,value:A}]}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Datos del Instituto Nacional de Estadística y Geografía ("},{type:b,tag:f,props:{href:"https:\u002F\u002Fx.com\u002FINEGI_INFORMA?s=20",rel:[h,i,j],target:k},children:[{type:a,value:"INEGI"}]},{type:a,value:"), con base en la Encuesta Nacional de Seguridad Pública Urbana (ENSU), 2020-2025; la Encuesta Nacional de Victimización de Empresas (ENVE), 2014-2024; el Censo Nacional de Gobierno Federal (CNGF), 2019-2024 y el Censo Nacional de Gobiernos Estatales (CNGE), 2024, ofrecen un panorama más amplio sobre la "},{type:b,tag:c,props:{},children:[{type:a,value:"percepción de corrupción en el país."}]}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"De acuerdo con el organismo, de enero a junio de 2025, "},{type:b,tag:c,props:{},children:[{type:a,value:"8.9 por ciento"}]},{type:a,value:" de las personas de 18 años y más, residentes de áreas urbanas, que realizaron de forma directa algún trámite, pago o solicitud de servicio ante un servidor público, fue "},{type:b,tag:c,props:{},children:[{type:a,value:"víctima de corrupción"}]},{type:a,value:"."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Durante el primer semestre de 2025, "},{type:b,tag:c,props:{},children:[{type:a,value:"45.2 por ciento"}]},{type:a,value:" de las personas de 18 años o más, pertenecientes a áreas urbanas que tuvieron contacto con autoridades específicamente de "},{type:b,tag:c,props:{},children:[{type:a,value:"seguridad pública"}]},{type:a,value:", fueron afectados por actos de este tipo. "}]},{type:a,value:d},{type:b,tag:l,props:{id:B},children:[{type:b,tag:f,props:{href:"#hacia-un-plan-nacional",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:b,tag:c,props:{},children:[{type:a,value:"Hacia un plan nacional"}]},{type:a,value:" "}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"El SNA se encuentra en la antesala de ser reformado y darle un nuevo impulso. Especialistas señalan que el reto es lograr el real funcionamiento de este sistema, por lo que llaman a revisar la obligatoriedad de la Política Nacional Anticorrupción y su Programa de Implementación, así como la operación de la Plataforma Digital Nacional, a la que aún algunos entes se resisten a incorporarse."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"El especialista Emiliano Montes de Oca menciona que desde los "},{type:b,tag:c,props:{},children:[{type:a,value:r}]},{type:a,value:" y la sociedad civil organizada, se ha planteado una propuesta de reforma que abre la posibilidad de "},{type:b,tag:c,props:{},children:[{type:a,value:"reactivar el sistema y hacerlo más eficaz"}]},{type:a,value:". No obstante, pese a las diferentes propuestas que se han planteado para la reforma, aún no hay un consenso claro sobre los cambios que debería incorporar."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"“Es necesario abrir el diálogo con autoridades, sociedad civil, academia y ciudadanía para recuperar todas las voces y devolverle vida al SNA o, incluso, plantear un nuevo mecanismo si así se requiere. Pero debemos actuar con urgencia, porque la corrupción sigue siendo, por mucho, una tarea pendiente”, asegura."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Acciones de la Secretaría Anticorrupción y Buen Gobierno (SABG), a cargo de "},{type:b,tag:c,props:{},children:[{type:a,value:D}]},{type:a,value:", podrían constituir los primeros pasos hacia el combate efectivo contra la corrupción."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Esta secretaría ha ido en pos de "},{type:b,tag:c,props:{},children:[{type:a,value:"grandes casos de corrupción"}]},{type:a,value:" en contratos de obras o adquisiciones, lo que ha sido reforzado con las reformas a leyes relacionadas a estos temas, instituyendo medidas de seguimiento de todo el procedimiento de contratación a través de la "},{type:b,tag:c,props:{},children:[{type:a,value:"Plataforma Nacional de Contrataciones Públicas"}]},{type:a,value:", desde la adjudicación del contrato hasta su cumplimiento. Dicha plataforma será implementada en un plazo de 30 meses a partir de abril próximo."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"La Secretaría Anticorrupción y Buen Gobierno cerró el 2025 indagando "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.reporteindigo.com\u002Fnacional\u002Fvalesgate-anticorrupcion-cierra-2025-con-investigacion-a-licitacion-de-vales-20251227-0013.html",rel:[h,i,j],target:k},children:[{type:a,value:"el llamado “valesgate”"}]},{type:a,value:", una licitación pública nacional de vales electrónicos de despensa destinados a trabajadores de nivel federal."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Esta investigación se trata de la segunda que emprende la secretaría a cargo de Buenrostro, que en abril del año pasado anuló la "},{type:b,tag:c,props:{},children:[{type:a,value:"megacompra de medicamentos"}]},{type:a,value:" consolidada debido a malas prácticas de funcionarios de Laboratorios de Biológicos y Reactivos de México (Birmex) y empresas participantes en la licitación."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"La indagatoria en torno a los vales de despensa se suscitó después de que "},{type:b,tag:c,props:{},children:[{type:a,value:"Toka Internacional S.A.P.I. de C.V.,"}]},{type:a,value:" una de las compañías que participó en el concurso, denunciara las supuestas anomalías en la licitación ganada por "},{type:b,tag:c,props:{},children:[{type:a,value:"Servicios Broxel S.A.P.I. de C.V."}]}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Adicionalmente, la secretaría contaba con información respecto a la "},{type:b,tag:c,props:{},children:[{type:a,value:"dispersión de 724 mil tarjetas"}]},{type:a,value:" en más de 2 mil 200 puntos del país, además de una serie de cuestionamientos sobre el cumplimiento de las condiciones económicas del fallo."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"De acuerdo con "},{type:b,tag:c,props:{},children:[{type:a,value:"Compras MX"}]},{type:a,value:", 224 entidades públicas, entre secretarías y organismos, adquirieron con Servicios Broxel S.A.P.I. de C.V, el suministro de vales electrónicos de despensa de fin de año. El organismo con mayor monto comprometido en esta licitación fue el IMSS Bienestar con 2 mil 327 millones 186 mil 300 pesos."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Acciones como estas, así como la plena instalación del SNA y los SEA, abonarán en el combate a este flagelo."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fsistema_nacional_anticorrupcion_sigue_incompleto_271_cargos_vacantes_y_sistemas_estatales_inoperantes",extension:".md",createdAt:"2026-07-19T00:56:17.261Z",updatedAt:"2026-07-19T00:56:17.262Z"}}],fetch:{},mutations:[]}}("text","element","strong","\n","p","a",3,"nofollow","noopener","noreferrer","_blank","h3","true",-1,"span","icon","icon-link","Comités de Participación Ciudadana","Sistemas Estatales Anticorrupción","sistemas-estatales-en-riesgo","Sistemas estatales en riesgo","inoperancia-el-enemigo-a-vencer","Inoperancia, el enemigo a vencer","una-década-complicada-para-la-institución","Una década complicada para la institución","víctimas-de-corrupción-en-méxico","Víctimas de corrupción en México","hacia-un-plan-nacional","Sistema Nacional Anticorrupción","Raquel Buenrostro")));